<script setup lang="ts">
import{computed,onMounted,ref}from"vue";
import{auth,nodes,inbounds,clients,traffic,audit,quotas,admins,configs}from"./api";
const sections=[["dashboard","داشبورد","Dashboard"],["nodes","نودها","Nodes"],["inbounds","این‌باندها","Inbounds"],["clients","کلاینت‌ها","Clients"],["traffic","ترافیک و سهمیه","Traffic & Usage"],["admins","مدیران و RBAC","Managers & RBAC"],["audit","گزارش حسابرسی","Audit Logs"],["settings","تنظیمات","Settings"]];
const artifact=ref<any>(null),section=ref("dashboard"),lang=ref<"fa"|"en">("fa"),drawer=ref(false),email=ref(""),password=ref(""),mfaToken=ref(""),mfaCode=ref(""),loginError=ref(""),loading=ref(false),booting=ref(true),me=ref<any>(null),modal=ref<string|null>(null),notice=ref("");
const nodeRows=ref<any[]>([]),inboundRows=ref<any[]>([]),clientRows=ref<any[]>([]),adminRows=ref<any[]>([]),auditRows=ref<any[]>([]),trafficData=ref<any>({});
const nodeForm=ref({name:"",address:"",agent_url:""}),inboundForm=ref({node_id:"",name:"",protocol:"wireguard",listen_port:51820,interface:"wg0",address:"10.10.0.1/24",network:"10.10.0.0/24",dns:"1.1.1.1"}),clientForm=ref({inbound_id:"",name:"",assigned_address:"10.10.0.2/32"}),adminForm=ref({email:"",password:"",role:"tenant_operator"}),quotaForm=ref({client_id:"",total_bytes:"",daily_bytes:"",monthly_bytes:"",max_devices:"",warning_ratio:80});
const title=computed(()=>{const s=sections.find(x=>x[0]===section.value);return s?.[lang.value==="fa"?1:2]??(lang.value==="fa"?"داشبورد":"Dashboard")});
const dir=computed(()=>lang.value==="fa"?"rtl":"ltr");
const t=(fa:string,en:string)=>lang.value==="fa"?fa:en;
async function load(){loading.value=true;try{me.value=await auth.me();const[n,i,c,t,a]=await Promise.all([nodes.list(),inbounds.list(),clients.list(),traffic.summary(),audit.list()]);nodeRows.value=n;inboundRows.value=i;clientRows.value=c;trafficData.value=t;if(me.value.role!=="tenant_operator")adminRows.value=await admins.list()}catch(e){if(localStorage.getItem("primevpn_access"))loginError.value=e instanceof Error?e.message:"خطای API"}finally{loading.value=false;booting.value=false}}
async function login(){loginError.value="";loading.value=true;try{const r=await auth.login(email.value,password.value);if(r.mfa_required){mfaToken.value=r.mfa_token;modal.value="mfa";return}localStorage.setItem("primevpn_access",r.access_token);await load()}catch(e){loginError.value=e instanceof Error?e.message:"ورود ناموفق"}finally{loading.value=false}}
async function verifyMfa(){try{const r=await auth.mfaVerify(mfaToken.value,mfaCode.value);localStorage.setItem("primevpn_access",r.access_token);modal.value=null;await load()}catch(e){loginError.value=e instanceof Error?e.message:"کد MFA نامعتبر"}}
async function act(fn:()=>Promise<any>,success="انجام شد"){try{await fn();notice.value=success;modal.value=null;await load()}catch(e){notice.value=e instanceof Error?e.message:"خطا"}}
async function issueConfig(id:string){try{const c=await clients.credential(id);artifact.value=await configs.download(c.artifact_id);modal.value="artifact"}catch(e){notice.value=e instanceof Error?e.message:"خطا در ساخت Config"}}
async function copyArtifact(){if(artifact.value?.payload)await navigator.clipboard.writeText(artifact.value.payload);notice.value="Config کپی شد"}
async function provision(id:string){try{const r=await nodes.provision(id);notice.value=r.bootstrap_token?"Bootstrap token ساخته شد؛ برای نصب Agent استفاده کن":"Provisioning ثبت شد";if(r.bootstrap_token)notice.value=`Bootstrap Token: ${r.bootstrap_token}`;modal.value=null;await load()}catch(e){notice.value=e instanceof Error?e.message:"Provisioning ناموفق"}}
function logout(){localStorage.removeItem("primevpn_access");me.value=null}
onMounted(load);
</script>
<template>
<div v-if="booting" class="app-shell"><main class="main"><div class="panel page"><div class="empty">در حال اتصال به PRIMEVPN Control Plane…</div></div></main></div>
<div v-else-if="!me" class="login-shell"><div class="login-card"><div class="brand"><span class="brand-mark">P</span><div><b>PRIMEVPN</b><small>Control Plane v100</small></div></div><h1>ورود به پنل</h1><p>مدیریت امن Node، Inbound، Client و Traffic</p><input v-model="email" type="email" placeholder="Email"><input v-model="password" type="password" placeholder="Password" @keyup.enter="login"><button class="primary wide" :disabled="loading" @click="login">{{loading?"در حال ورود…":"ورود"}}</button><div v-if="loginError" class="error-box">{{loginError}}</div></div></div>
<div v-else class="app-shell" :dir="dir">
<div v-if="drawer" class="drawer-backdrop" @click="drawer=false"></div>
<aside class="sidebar" :class="{open:drawer}"><div class="brand"><span class="brand-mark">P</span><div><b>PRIMEVPN</b><small>Control Plane v100</small></div></div><nav><button v-for="s in sections" :key="s[0]" :class="{active:section===s[0]}" @click="section=s[0];drawer=false"><span class="nav-icon">{{["⌂","♙","▤","◎","▣","◈","⌁","⚙"][sections.indexOf(s)]}}</span><span>{{s[lang==="fa"?1:2]}}</span><small>{{s[lang==="fa"?2:1]}}</small></button></nav><div class="sidebar-foot"><i></i>{{me.email}}<button class="icon" @click="logout">خروج</button></div></aside>
<main class="main"><header><button class="mobile-menu" @click="drawer=true">☰</button><div class="top-brand"><span class="brand-mark">P</span><div><b>PRIME<span>VPN</span></b><small>Secure · Fast · Global</small></div></div><div class="header-spacer"></div><div class="account-pill"><i></i><div><b>{{me.role}}</b><small>Tenant</small></div><span>●</span></div><div class="language"><button :class="{on:lang==="fa"}" @click="lang='fa'">فارسی</button><button :class="{on:lang==="en"}" @click="lang='en'">English</button></div></header><div v-if="notice" class="notice" @click="notice=''">{{notice}}</div>
<div v-if="loading" class="panel"><div class="empty">در حال دریافت داده…</div></div>
<section v-else-if="section==='dashboard'" class="dashboard-home"><div class="welcome-row"><div><small>Welcome back,</small><h1>{{t("خوش آمدید","Welcome back")}}</h1><p>{{t("به پنل مدیریت PRIMEVPN","PRIMEVPN Control Panel")}}</p><div class="service-status"><i></i><b>{{t("وضعیت سرویس: آنلاین","Service Status: Online")}}</b><small>Service Status: Online</small></div></div><div class="hero-shield">P</div></div><div class="stats dashboard-stats"><article><span class="stat-icon users">♟</span><small>{{t("کاربران فعال","Active Users")}}</small><strong>{{clientRows.length}}</strong><em>↑ 0% <small>{{t("نسبت به دیروز","vs yesterday")}}</small></em></article><article><span class="stat-icon nodes">▤</span><small>{{t("نودها","Nodes")}}</small><strong>{{nodeRows.length}}</strong><em>↑ 0% <small>{{t("نسبت به دیروز","vs yesterday")}}</small></em></article><article><span class="stat-icon plans">◎</span><small>{{t("اینترنت‌ها","Plans")}}</small><strong>{{inboundRows.length}}</strong><em>↑ 0% <small>{{t("نسبت به دیروز","vs yesterday")}}</small></em></article><article><span class="stat-icon traffic">⌁</span><small>{{t("کل ترافیک","Total Traffic")}}</small><strong>{{((trafficData.total_bytes||0)/1099511627776).toFixed(2)}} TB</strong><em>↑ 0% <small>{{t("نسبت به دیروز","vs yesterday")}}</small></em></article></div><div class="panel traffic-card"><div class="panel-head"><div><h2>{{t("مصرف ترافیک","Traffic Usage")}}</h2><small>Traffic Usage</small></div><button class="period">{{t("۷ روز گذشته","Last 7 days")}} ▣</button></div><div class="chart"><div v-for="n in [30,48,38,47,35,42,58]" :key="n" class="bar" :style="{height:n+'%'}"></div></div><div class="days"><span v-for="d in (lang==='fa'?['شنبه','یکشنبه','دوشنبه','سه‌شنبه','چهارشنبه','پنجشنبه','جمعه']:['Sat','Sun','Mon','Tue','Wed','Thu','Fri'])" :key="d">{{d}}</span></div></div><div class="panel activity-card"><div class="panel-head"><div><h2>{{t("فعالیت‌های اخیر","Recent Activity")}}</h2><small>Recent Activity</small></div><button class="link">{{t("مشاهده همه","View all")}} ›</button></div><div class="activity"><div><span class="activity-icon users">♟</span><div><b>{{t("ورود کاربر","User login")}}</b><small>{{me.role}}</small></div><time>23:41</time><i></i></div><div><span class="activity-icon nodes">▤</span><div><b>{{t("نود متصل شد","Node connected")}}</b><small>Node #1</small></div><time>22:18</time><i></i></div><div><span class="activity-icon plans">◎</span><div><b>{{t("پلن جدید فعال شد","New plan activated")}}</b><small>Premium 1 Month</small></div><time>20:45</time><i></i></div></div></div><div class="mobile-lang"><button @click="lang='en'">English</button><b>|</b><button @click="lang='fa'">فارسی</button><small>v1.0.0</small></div></section>
<section v-else-if="section==='nodes'"><div class="panel page"><div class="panel-head"><h2>نودها</h2><button v-if="me.role!=='tenant_operator'" class="primary" @click="modal='node'">+ نود جدید</button></div><div class="table"><div class="tr th"><span>نام</span><span>آدرس</span><span>State</span><span>عملیات</span></div><div class="tr" v-for="n in nodeRows" :key="n.id"><span>{{n.name}}</span><span>{{n.address}}</span><span>{{n.state}}</span><span><button v-if="me.role!=='tenant_operator'" class="icon" @click="provision(n.id)">Provision</button></span></div></div></div></section>
<section v-else-if="section==='inbounds'"><div class="panel page"><div class="panel-head"><h2>این‌باندها</h2><button v-if="me.role!=='tenant_operator'" class="primary" @click="modal='inbound'">+ Inbound جدید</button></div><div class="table"><div class="tr th"><span>نام</span><span>Protocol</span><span>Port</span><span>State</span></div><div class="tr" v-for="x in inboundRows" :key="x.id"><span>{{x.name}}</span><span>{{x.protocol}}</span><span>{{x.listen_port}}</span><span>{{x.desired_state}}</span></div></div></div></section>
<section v-else-if="section==='clients'"><div class="panel page"><div class="panel-head"><h2>کلاینت‌ها</h2><button v-if="me.role!=='tenant_operator'" class="primary" @click="modal='client'">+ Client جدید</button></div><div class="table"><div class="tr th"><span>نام</span><span>Inbound</span><span>Address</span><span>عملیات</span></div><div class="tr" v-for="x in clientRows" :key="x.id"><span>{{x.name}}</span><span>{{x.inbound_id}}</span><span>{{x.assigned_address}}</span><span><button class="icon" @click="issueConfig(x.id)">Config</button><button class="icon" @click="act(()=>clients.revoke(x.id),'کلاینت revoke شد')">Revoke</button></span></div></div></div></section>
<section v-else-if="section==='traffic'"><div class="grid2"><div class="panel"><h2>Traffic</h2><strong>{{((trafficData.total_bytes||0)/1099511627776).toFixed(2)}} TB</strong><p>IN: {{((trafficData.bytes_in||0)/1073741824).toFixed(2)}} GB</p><p>OUT: {{((trafficData.bytes_out||0)/1073741824).toFixed(2)}} GB</p></div><div class="panel"><h2>Quota</h2><button v-if="me.role!=='tenant_operator'" class="primary" @click="modal='quota'">تنظیم سهمیه</button></div></div></section>
<section v-else-if="section==='admins'"><div class="panel page"><div class="panel-head"><h2>مدیران و RBAC</h2><button v-if="me.role!=='tenant_operator'" class="primary" @click="modal='admin'">+ مدیر</button></div><div class="table"><div class="tr th"><span>Email</span><span>Role</span><span>Enabled</span><span></span></div><div class="tr" v-for="a in adminRows" :key="a.id"><span>{{a.email}}</span><span>{{a.role}}</span><span>{{a.enabled?'YES':'NO'}}</span><span></span></div></div></div></section>
<section v-else-if="section==='audit'"><div class="panel page"><h2>Audit Logs</h2><div class="table"><div class="tr th"><span>Action</span><span>Resource</span><span>Result</span><span>Time</span></div><div class="tr" v-for="x in auditRows" :key="x.id"><span>{{x.action}}</span><span>{{x.resource}}</span><span>{{x.result}}</span><span>{{x.created_at}}</span></div></div></div></section>
<section v-else><div class="panel page"><h2>Settings</h2><div class="empty">تنظیمات امنیتی و عملیاتی از طریق Environment/Control Plane مدیریت می‌شوند.</div></div></section>
</main>
</div>
<div v-if="modal" class="modal-backdrop"><div class="modal">
<button class="close" @click="modal=null">×</button>
<div v-if="modal==='artifact'"><h2>Config Artifact</h2><p>{{artifact?.protocol}}</p><textarea class="artifact" readonly :value="artifact?.payload"></textarea><button class="primary wide" @click="copyArtifact">کپی Config</button></div><div v-if="modal==='mfa'"><h2>تأیید MFA</h2><input v-model="mfaCode" inputmode="numeric" placeholder="کد ۶ رقمی"><button class="primary wide" @click="verifyMfa">تأیید</button></div>
<div v-if="modal==='node'"><h2>Node جدید</h2><input v-model="nodeForm.name" placeholder="Name"><input v-model="nodeForm.address" placeholder="Public address"><input v-model="nodeForm.agent_url" placeholder="https://node:9100"><button class="primary wide" @click="act(()=>nodes.create(nodeForm),'Node ساخته شد')">ساخت</button></div>
<div v-if="modal==='inbound'"><h2>Inbound جدید</h2><select v-model="inboundForm.node_id"><option value="">Node</option><option v-for="n in nodeRows" :value="n.id">{{n.name}}</option></select><select v-model="inboundForm.protocol"><option value="wireguard">WireGuard</option><option value="amneziawg">AmneziaWG</option><option value="openvpn">OpenVPN</option></select><input v-model="inboundForm.name" placeholder="Name"><input v-model.number="inboundForm.listen_port" type="number" placeholder="Port"><input v-model="inboundForm.interface" placeholder="Interface"><input v-model="inboundForm.address" placeholder="Address/CIDR"><input v-model="inboundForm.network" placeholder="Network/CIDR"><input v-model="inboundForm.dns" placeholder="DNS"><button class="primary wide" @click="act(()=>inbounds.create(inboundForm),'Inbound ساخته شد')">ساخت</button></div>
<div v-if="modal==='client'"><h2>Client جدید</h2><select v-model="clientForm.inbound_id"><option value="">Inbound</option><option v-for="i in inboundRows" :value="i.id">{{i.name}} / {{i.protocol}}</option></select><input v-model="clientForm.name" placeholder="Name"><input v-model="clientForm.assigned_address" placeholder="10.10.0.2/32"><button class="primary wide" @click="act(()=>clients.create(clientForm),'Client ساخته شد')">ساخت</button></div>
<div v-if="modal==='admin'"><h2>Admin جدید</h2><input v-model="adminForm.email" placeholder="Email"><input v-model="adminForm.password" type="password" placeholder="Password ≥ 12 chars"><select v-model="adminForm.role"><option value="tenant_operator">Operator</option><option value="tenant_manager">Manager</option></select><button class="primary wide" @click="act(()=>admins.create(adminForm),'Admin ساخته شد')">ساخت</button></div>
<div v-if="modal==='quota'"><h2>Quota</h2><select v-model="quotaForm.client_id"><option value="">Client</option><option v-for="c in clientRows" :value="c.id">{{c.name}}</option></select><input v-model="quotaForm.total_bytes" type="number" placeholder="Total bytes"><input v-model="quotaForm.daily_bytes" type="number" placeholder="Daily bytes"><input v-model="quotaForm.monthly_bytes" type="number" placeholder="Monthly bytes"><input v-model="quotaForm.max_devices" type="number" placeholder="Max devices"><input v-model.number="quotaForm.warning_ratio" type="number" placeholder="Warning %"><button class="primary wide" @click="act(()=>quotas.set({...quotaForm,total_bytes:quotaForm.total_bytes?Number(quotaForm.total_bytes):null,daily_bytes:quotaForm.daily_bytes?Number(quotaForm.daily_bytes):null,monthly_bytes:quotaForm.monthly_bytes?Number(quotaForm.monthly_bytes):null,max_devices:quotaForm.max_devices?Number(quotaForm.max_devices):null}),'Quota ذخیره شد')">ذخیره</button></div>
</div></div>
</template>